277	    match result {
278	        Ok(_) => None,
279	        Err(RunError::Agent(err)) => Some(AgentEvent::RunFailed {
280	            error: err.to_string(),
281	        }),
282	        Err(RunError::Cancelled) => Some(RunInterrupt::Cancelled.terminal_event()),
