285	        // Infrastructure failures have no canonical interrupt text; their own
286	        // message is the most informative thing available. Not a `RunInterrupt`,
287	        // so the frame is built here rather than in core.
288	        Err(other) => Some(AgentEvent::RunFailed {
289	            error: other.to_string(),
290	        }),
291	    }
